import csv, collections
from decimal import Decimal, ROUND_HALF_UP

def num(s):
    s=(s or '').strip()
    return Decimal(s) if s else Decimal(0)

def load(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

def agg(rows):
    d = collections.defaultdict(lambda: [Decimal(0), Decimal(0)])
    for r in rows:
        d[r['conta']][0] += num(r['debito'])
        d[r['conta']][1] += num(r['credito'])
    return d

base = '/work/workspace/documents'
months = ['01','02','03']
raz = {m: load(f'{base}/mes_{m}/razao.csv') for m in months}
bal = {m: load(f'{base}/mes_{m}/balancete.csv') for m in months}

for m in months:
    td = sum(num(r['debito']) for r in raz[m])
    tc = sum(num(r['credito']) for r in raz[m])
    print(f'mes {m}: razao deb={td} cred={tc} equilibrado={td==tc}')

pl = ['3.1.01','2.1.02','2.1.03','4.1.02','4.2.01','4.2.02','4.2.03','4.2.04','4.3.01','4.4.01','4.4.02']
cum = collections.defaultdict(lambda: [Decimal(0), Decimal(0)])
for m in months:
    a = agg(raz[m])
    for k,(d,c) in a.items():
        cum[k][0]+=d; cum[k][1]+=c
    print(f'--- mes {m} ---')
    for k in pl:
        if k in a:
            print(f'  {k}: deb={a[k][0]} cred={a[k][1]}')

print('--- cumul razao vs balancete mar (conta a conta) ---')
bm = agg(bal['03'])
diffs=[]
for k in sorted(set(cum)|set(bm)):
    cd = cum[k][0]-cum[k][1]
    bd = (bm[k][0]-bm[k][1]) if k in bm else None
    if bd is None or cd != bd:
        diffs.append((k, str(cd), str(bd)))
print('divergencias:', diffs if diffs else 'NENHUMA')

a1 = agg(raz['01'])
rec = a1['3.1.01'][1]-a1['3.1.01'][0]
desp = sum((a1[k][0]-a1[k][1]) for k in pl if k!='3.1.01' and k in a1)
print('jan: receita', rec, '| despesas', desp, '| resultado sem estorno', rec-desp, '| com estorno', rec-desp-Decimal('11100'))
print('jan 4.2.02 =', a1['4.2.02'][0], '| fev 4.2.02 =', agg(raz['02'])['4.2.02'][0], '| mar 4.2.02 =', agg(raz['03'])['4.2.02'][0], '| cumul =', cum['4.2.02'][0])

def r2(x): return x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
ll=Decimal('604149'); antes=ll+Decimal('78000')
trava=antes*Decimal('0.30'); lr=antes-trava
irpj=r2(lr*Decimal('0.15')); adic=r2((lr-Decimal('60000'))*Decimal('0.10')); csll=r2(lr*Decimal('0.09'))
semcomp=r2(antes*Decimal('0.15'))+r2((antes-Decimal('60000'))*Decimal('0.10'))+r2(antes*Decimal('0.09'))
print('antes',antes,'trava',trava,'lucro real',lr,'IRPJ',irpj,'adicional',adic,'CSLL',csll,'total',irpj+adic+csll)
print('sem compensacao',semcomp,'economia',semcomp-(irpj+adic+csll))
print('parteB',Decimal('900000')-trava,'trimestres extras',(Decimal('900000')-trava)/trava)
EOF"}

